async function ensureNavigation(m){if(busy)throw Error('انتظر اكتمال تحميل النموذج.');endQuiz();if(mode!==m)await activate(m);if(!datasets[m]||root!==datasets[m].root)throw Error('تعذّر فتح النموذج.');}
