 for(const button of document.querySelectorAll('[data-panel]'))button.onclick=()=>{document.body.dataset.panel=document.body.dataset.panel===button.dataset.panel?'none':button.dataset.panel;};for(const button of document.querySelectorAll('.close-panel'))button.onclick=()=>document.body.dataset.panel='none';
