function filterLandmarkRows(){const q=$('pinSearch').value.toLowerCase();for(const b of $('landmarkList').children)b.hidden=!b.dataset.search.includes(q);}
function snapLandmark(r,point){let nearest=new THREE.Vector3(...point),distance=Infinity;const candidate=new THREE.Vector3(),target=new THREE.Vector3(...point);for(const mesh of r.meshes){const attr=mesh.geometry.attributes.position;for(let i=0;i<attr.count;i++){candidate.fromBufferAttribute(attr,i);mesh.localToWorld(candidate);r.object.worldToLocal(candidate);const d=candidate.distanceToSquared(target);if(d<distance){distance=d;nearest.copy(candidate);}}}return nearest.toArray();}
const overviewBoneBounds={"femur": [[-0.1480480283498764, 0.433040589094162, -0.05850019305944443], [-0.03270915895700455, 0.8839107155799866, 0.018447428941726685]], "tibia": [[-0.1145222932100296, 0.07542404532432556, -0.06001882627606392], [-0.0379505380988121, 0.4345637559890747, 0.002808157354593277]], "fibula": [[-0.1242465078830719, 0.057020097970962524, -0.059527479112148285], [-0.08956530690193176, 0.41708481311798096, -0.027131985872983932]], "patella": [[-0.10579638183116913, 0.4242987036705017, -0.00540022412315011], [-0.062749482691288, 0.46471279859542847, 0.015049876645207405]]};
function landmarkSet(r){if(!r)return [];if(mode==='arm'){const id=r.id.replace('_left','_right');return landmarks[id]||extraLandmarks[id]||[];}const k=boneKey(r.name);const pins=['femur','tibia','fibula','patella'].includes(k)?extraLandmarks[k]:[];if(mode!=='leg'||!pins.length)return pins;const old=overviewBoneBounds[k],bounds=r.meta.bounds;return pins.map(p=>({...p,position:p.position.map((v,i)=>bounds[0][i]+(v-old[0][i])/(old[1][i]-old[0][i])*(bounds[1][i]-bounds[0][i]))}));}
function renderLandmarks(){
 landmarkElements=[];$('landmarkOverlay').replaceChildren();$('landmarkList').replaceChildren();$('unplacedPins').replaceChildren();$('landmarkDescription').textContent='';$('landmarkSpeech').hidden=true;$('pinReveal').hidden=true;activeLandmark=null;
 const key=selected&&boneKey(selected.name),available=landmarkSet(selected),pending=key?unplaced[key]||[]:[];
 $('landmarkSection').hidden=!selected; if(!selected)return;
 $('pinSearch').value='';$('pinSource').href=sourceFor(selected.name);$('pinSource').hidden=!key;
 const detailMode=['femur','tibia','fibula','patella','hip bone'].includes(key)?'leg':'arm';const detailedId=key&&['clavicle','scapula','humerus','radius','ulna','femur','tibia','fibula','patella','hip bone'].includes(key)?(key==='hip bone'?'hip':key)+(/left/i.test(selected.name)?'_left':'_right'):null;
 $('openDetailed').hidden=mode!=='body'||!detailedId;
 $('openDetailed').onclick=async()=>{await ensureNavigation(detailMode);const r=records.find(r=>r.id===detailedId);if(r){select(r);isolation=true;updateVisibility();focusRecord(r);}};
 const triangles=selected.meshes.reduce((n,m)=>n+(m.geometry.index?.count||m.geometry.attributes.position.count)/3,0);
 $('modelQuality').textContent=Math.round(triangles).toLocaleString('en-US')+' مثلثًا هندسيًا · '+(mode!=='body'?'نموذج أكثر تفصيلًا':'نموذج عام')+' · ليست خامة 16K';
 $('pinCoverage').textContent=available.length+' علامة 3D تقديرية · '+pending.length+' معلمًا لم يُثبّت بعد';
 $('landmarkHelp').textContent=available.length?'مواضع تعليمية تقديرية على سطح النموذج، غير مراجعة تشريحيًا. بعض التفاصيل الصغيرة غير ممثلة. اضغط اسمًا لعزل العظمة وتغيير زاوية العرض.':'لا توجد Pins مثبتة لهذا النموذج حتى الآن.';
 $('pinRecall').hidden=!available.length;$('pinSearch').hidden=!available.length;
 for(const [i,item] of available.entries()){
 selected.landmarkPositions??={};const pin={...item,position:selected.landmarkPositions[item.id]??=snapLandmark(selected,item.position)};
 const button=document.createElement('button');button.className='anatomy-pin';button.textContent=String(i+1);button.setAttribute('aria-label',recallPins?'العلامة '+(i+1):item.name+' — '+item.ar);
 const row=document.createElement('button');row.className='landmark-row';row.dataset.search=(item.name+' '+item.ar).toLowerCase();row.textContent=recallPins?'العلامة '+(i+1):(i+1)+' · '+item.name+' — '+item.ar;
 const reveal=()=>{$('landmarkDescription').textContent=(i+1)+' · '+item.name+' — '+item.ar+' — '+item.description;$('pinReveal').hidden=true;$('landmarkSpeech').hidden=false;$('landmarkSpeech').onclick=()=>speakTerm(item.name);};
 const show=()=>{activeLandmark=item.id;isolation=true;updateVisibility();const view=[...item.view];if(/left/i.test(selected.name))view[0]*=-1;const box=new THREE.Box3().setFromObject(selected.object);fit(box,new THREE.Vector3(...view));const world=selected.object.localToWorld(new THREE.Vector3(...pin.position));const direction=visibleLandmarkDirection(selected.meshes,world,box,camera.position.distanceTo(controls.target),new THREE.Vector3(...view));fit(box,direction);for(const x of landmarkElements){x.button.classList.toggle('active',x.pin.id===activeLandmark);x.row.classList.toggle('active',x.pin.id===activeLandmark);x.button.dataset.label=(!recallPins&&x.pin.id===activeLandmark)?x.pin.name:'';}if(recallPins){$('landmarkDescription').textContent='ما اسم العلامة '+(i+1)+'؟';$('pinReveal').hidden=false;$('landmarkSpeech').hidden=true;$('pinReveal').onclick=reveal;}else reveal();};
 button.onclick=show;row.onclick=show;$('landmarkOverlay').append(button);$('landmarkList').append(row);landmarkElements.push({pin,r:selected,button,row});
 }
 if(pending.length){const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='معالم أخرى للمراجعة · لم تُثبّت على 3D ('+pending.length+')';details.append(summary);for(const term of pending){const b=document.createElement('button');b.className='unplaced-pin';b.textContent=term+' ◖';b.title='اسمع الاسم — لا توجد علامة 3D مثبتة';b.onclick=()=>speakTerm(term);details.append(b);}$('unplacedPins').append(details);}
}
function speakTerm(term){if(!('speechSynthesis' in window)){toast('الصوت غير متاح.');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(term);u.lang='en-US';u.rate=.8;u.onerror=()=>toast('تعذّر تشغيل الصوت؛ تأكد من وجود صوت إنجليزي على الجهاز.');speechSynthesis.speak(u);}
function updateLandmarkPositions(){for(const entry of landmarkElements){const {pin,r,button}=entry;if(!$('showLandmarks').checked||quiz||!r.object.visible){button.hidden=true;continue;}const world=r.object.localToWorld(new THREE.Vector3(...pin.position)),projected=world.clone().project(camera);const key=[...camera.position.toArray(),...camera.quaternion.toArray(),...world.toArray()].join(',');if(entry.occlusionKey!==key){entry.occlusionKey=key;const direction=world.clone().sub(camera.position),distance=direction.length();const test=new THREE.Raycaster(camera.position,direction.normalize(),0,distance);const first=test.intersectObjects(r.meshes,false)[0];const tolerance=new THREE.Box3().setFromObject(r.object).getSize(new THREE.Vector3()).length()*.009;entry.occluded=!!first&&first.distance<distance-tolerance;}button.hidden=entry.occluded||projected.z<-1||projected.z>1||Math.abs(projected.x)>1||Math.abs(projected.y)>1;if(!button.hidden){button.style.left=((projected.x+1)*viewport.clientWidth/2)+'px';button.style.top=((-projected.y+1)*viewport.clientHeight/2)+'px';}}}

$('pinsButton').onclick=()=>$('pinsMenu').showModal();
$('closePinsMenu').onclick=()=>$('pinsMenu').close();
$('togglePinsMenu').onclick=()=>{$('showLandmarks').checked=!$('showLandmarks').checked;renderLandmarks();$('pinsMenu').close();};
for(const [value,label] of regions){if(value==='all')continue;const b=document.createElement('button');b.textContent=label;b.onclick=async()=>{if(busy)return;$('pinsMenu').close();$('showLandmarks').checked=true;if(value==='upper'||value==='shoulder')await activate('arm');else if(value==='lower'||value==='pelvic')await activate('leg');else await chooseRegion(value);document.body.dataset.panel='explorer';toast('اختار عظمة لعرض أرقام المعالم وأسمائها.');};$('pinsRegions').append(b);}
